/* The local safety copy must remain visible and usable while a large PDF export
 * is still working. All PDF and project data are generated by the test. */
'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),Module=require('node:module');
const {chromium}=require(process.env.CODEX_PRIMARY_RUNTIME_NODE_MODULES?process.env.CODEX_PRIMARY_RUNTIME_NODE_MODULES+'/playwright':'playwright');
const fixtureFile=path.resolve(__dirname,'smartmatch-read-open-browser-v9-10.cjs'),fixtureModule=new Module(fixtureFile,module);
fixtureModule.filename=fixtureFile;fixtureModule.paths=Module._nodeModulePaths(__dirname);
let fixtureSource=fs.readFileSync(fixtureFile,'utf8').split('(async()=>{await new Promise(resolve=>server.listen')[0].replace("revision='9-10'","revision='9-12'");
fixtureModule._compile(fixtureSource+'\nmodule.exports={server,url,fixture,ready,instrument};',fixtureFile);
const {server,url,fixture,ready,instrument}=fixtureModule.exports;

(async()=>{
 await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));let browser,context;
 try{
  browser=await chromium.launch({executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});
  context=await browser.newContext({viewport:{width:390,height:667},isMobile:true,hasTouch:true,deviceScaleFactor:2});
  await context.route('**/auth/guard.js*',route=>route.fulfill({contentType:'application/javascript',body:"document.addEventListener('DOMContentLoaded',()=>document.documentElement.removeAttribute('data-auth-pending'));"}));
  const page=await context.newPage(),errors=[];page.on('pageerror',error=>errors.push(error.message));
  await page.goto(url());await instrument(page);const input=await fixture();
  await page.locator('#pwFile').setInputFiles({name:'lokal-sakerhetskopia.pdf',mimeType:'application/pdf',buffer:input.bytes});await ready(page);
  // Keep the independent PDF export pending after the prepared project is open.
  await page.evaluate(()=>{PDFLib.PDFDocument.load=()=>new Promise(()=>{});});
  await page.locator('#smartPdfInspect').click();await page.waitForSelector('#smartExportDialog[open]');
  const button=page.locator('#smartWorkspaceSaveLocal'),box=await button.boundingBox();
  assert(box,'local save is visible');assert(box.y>=0&&box.y+box.height<=667,'local save is inside the initial phone viewport');
  assert.equal(await button.isEnabled(),true);assert.equal(await button.innerText(),'Spara lokalt nu');
  assert(await page.locator('#smartExportProgress').isVisible(),'PDF preparation can continue independently');
  await button.click();await page.waitForFunction(()=>document.getElementById('smartLocalBackupStatus')?.textContent.startsWith('Sparad lokalt.'));
  assert.equal(await button.innerText(),'✓ Sparad lokalt');
  const projects=await page.evaluate(()=>SmartMatchSession.listProjects());
  assert.equal(projects.length,1);assert.equal(projects[0].name,'lokal-sakerhetskopia.pdf');assert.deepEqual(errors,[]);
  console.log('PASS phone: Spara lokalt is visible before PDF completion and stores a complete local project independently');
 }finally{await context?.close();await browser?.close();await new Promise(resolve=>server.close(resolve));}
})().catch(error=>{console.error(error);process.exitCode=1;});
